-- Send offsets of the effects redrawn in place with art bigger than a tile (pair 36, client/MANIFEST.md "Purchased
-- effect packs (pair 36)"). The engine draws such an effect with its bottom-right tile on the tile it is sent to, and
-- the in-place art kept that tile on the target, so a 3x3 or 4x4 art sat up and left of it. The table
-- ChaosFxSendOffset (data/lib/chaos_fx_send_offsets.lua, generated by client/tools/sprites/gen_fx_send_offsets.py)
-- gives the tile to send each such id at. Pure logic: tests/fx_send_offset_test.lua.
ChaosFxSendOffsetCore = ChaosFxSendOffsetCore or {}
local M = ChaosFxSendOffsetCore

-- -> x, y to send `effect` at for the target x, y (unchanged for an id not in `tbl`)
function M.shift(x, y, effect, tbl)
	local o = tbl and tbl[effect]
	if not o then
		return x, y
	end
	return x + o[1], y + o[2]
end

-- the table, loaded once from data/lib (nil when the file is missing: nothing is shifted); `reread` loads the file
-- again (a scripts reload picks up a new table)
function M.load(reread)
	if ChaosFxSendOffset == nil or reread then
		pcall(dofile, "data/lib/chaos_fx_send_offsets.lua")
	end
	return ChaosFxSendOffset
end

-- true once the engine shifts the effects itself (src-patch 0070 took the table): the Lua guard of
-- Position:sendMagicEffect then sends at the target tile, so no effect is shifted twice
M.engine = M.engine or false

-- hand the table to the engine (src-patch 0070, `G` = the engine's Game table). An engine without the patch has no
-- Game.setFxSendOffsets: M.engine stays false and the Lua guard shifts the Lua sends as before. -> M.engine
function M.applyEngine(G, reread)
	if type(G) ~= "table" or type(G.setFxSendOffsets) ~= "function" then
		M.engine = false
		return false
	end
	local t = M.load(reread)
	local ok, n = pcall(G.setFxSendOffsets, type(t) == "table" and t or {})
	M.engine = ok and type(n) == "number" or false
	return M.engine
end

-- does the Lua guard shift `effect` (its table has the id and the engine does not shift it)
function M.luaShifts(effect, tbl)
	return not M.engine and tbl ~= nil and tbl[effect] ~= nil
end

return M
